
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_hse12_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_hse12", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.030331730070750e+00, -2.973440182858239e+00, -2.893805149076567e+00, -2.783668448724959e+00, -2.633970774293729e+00, -2.435530708398784e+00, -2.181722884951848e+00, -1.872813889807001e+00, -1.519226147570919e+00, -1.140426276110750e+00, -7.772621656145554e-01, -5.411593677742237e-01, -4.754124873291131e-01, -3.931312980829096e-01, -2.883527577471740e-01, -1.869991689865394e-01, -1.078312241666781e-01, -4.662741693315717e-02, -1.080362923786578e-02, -1.216196345441310e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


